const dirs={up:'↑',left:'←',right:'→',down:'↓'};
const keyboard={ArrowUp:'up',w:'up',W:'up',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowDown:'down',s:'down',S:'down'};
export function mountCham(root,beep){
 let phase='ready',score=0,streak=0,lives=3,enemy=null,choice=null,deadline=0,best=0,timers=[],active=true;
 try{best=Number(localStorage.getItem('gyu_cham_best'))||0}catch{}
 root.insertAdjacentHTML('beforeend',`<div class="cham-game"><div class="cham-score"><span>SCORE <b data-score>0</b></span><span>BEST <b data-best>${best}</b></span><span data-lives>♥ ♥ ♥</span></div><div class="cham-arena"><div class="cham-burst" aria-hidden="true"></div><div class="cham-enemy-arrow" aria-hidden="true"></div><img class="cham-friend" src="character.png" alt="참참참을 하는 중앙 캐릭터"><div class="cham-choice" aria-hidden="true"></div><strong class="cham-call">참 · 참 · 참!</strong></div><p class="cham-status" role="status">같은 방향이면 걸려요. 다른 방향으로 피해 보세요!</p><progress class="cham-time" max="100" value="100" aria-label="방향 선택 남은 시간"></progress><div class="cham-directions">${Object.entries(dirs).map(([dir,arrow])=>`<button data-dodge="${dir}" aria-label="${{up:'위',left:'왼쪽',right:'오른쪽',down:'아래'}[dir]} 방향 선택">${arrow}</button>`).join('')}</div><button class="cham-start">게임 시작</button><p class="cham-help">“피해!”가 나오면 방향을 선택 · WASD / 방향키 / 버튼<br>목숨 3개 · 성공할수록 빨라져요</p></div>`);
 const q=s=>root.querySelector(s),arena=q('.cham-arena');
 const later=(fn,ms)=>timers.push(setTimeout(()=>{if(active)fn()},ms));
 function clear(){timers.forEach(clearTimeout);timers=[]}
 function controls(){root.querySelectorAll('[data-dodge]').forEach(b=>b.disabled=phase!=='choose');q('.cham-start').hidden=!['ready','over','paused'].includes(phase)}
 function stats(){q('[data-score]').textContent=score;q('[data-best]').textContent=best;q('[data-lives]').textContent='♥ '.repeat(lives)+'♡ '.repeat(3-lives)}
 function round(){clear();phase='count';choice=null;enemy=Object.keys(dirs)[Math.floor(Math.random()*4)];arena.classList.remove('win','lose');q('.cham-choice').textContent='';q('.cham-enemy-arrow').textContent='';q('.cham-time').value=100;q('.cham-status').textContent='준비… 캐릭터의 방향을 피해요!';controls();const beat=Math.max(240,420-score*12);for(let i=0;i<3;i++)later(()=>{q('.cham-call').textContent=['참!','참! 참!','참! 참! 참!'][i];beep(500+i*100,.04)},i*beat);later(()=>{phase='choose';deadline=performance.now()+Math.max(650,1400-score*45);q('.cham-call').textContent='피해!';q('.cham-status').textContent='지금! 한 방향을 선택하세요.';beep(1000,.07);controls()},beat*3)}
 function finish(dir){if(phase!=='choose')return;phase='reveal';choice=dir;controls();q('.cham-choice').textContent=dir?`YOU ${dirs[dir]}`:'시간 초과';q('.cham-enemy-arrow').textContent=dirs[enemy];const win=!!dir&&dir!==enemy;arena.classList.add(win?'win':'lose');q('.cham-call').textContent=win?'피했다!':'잡았다!';if(win){score++;streak++;q('.cham-status').textContent=`${streak}연속 성공! 다음에도 피해 봐요.`;beep(900,.1);if(score>best){best=score;try{localStorage.setItem('gyu_cham_best',String(best))}catch{}}}else{lives--;streak=0;q('.cham-status').textContent=dir?'같은 방향! 목숨 하나를 잃었어요.':'조금 늦었어요! 목숨 하나를 잃었어요.';beep(230,.12)}stats();later(()=>{if(lives>0)round();else{phase='over';q('.cham-call').textContent='GAME OVER';q('.cham-status').textContent=`${score}점! 다시 도전해서 최고 기록을 넘겨 봐요.`;q('.cham-start').textContent='다시 도전';controls()}},950)}
 function start(){if(!['ready','over','paused'].includes(phase))return;if(phase!=='paused'){score=0;lives=3;streak=0}stats();round()}
 q('.cham-start').onclick=start;root.querySelectorAll('[data-dodge]').forEach(b=>b.onclick=()=>finish(b.dataset.dodge));
 function key(e){if(e.repeat||e.target.closest('input,textarea,select'))return;const dir=keyboard[e.key];if(dir){e.preventDefault();finish(dir)}else if(e.key==='Enter'&&['ready','over','paused'].includes(phase)){e.preventDefault();start()}}
 function visibility(){if(document.hidden&&!['ready','over'].includes(phase)){clear();phase='paused';q('.cham-call').textContent='잠깐 쉬는 중';q('.cham-status').textContent='돌아오면 계속할 수 있어요.';q('.cham-start').textContent='계속하기';controls()}}
 const padListeners=Array.from(document.querySelectorAll('[data-dir]')).map(b=>{const fn=()=>finish(b.dataset.dir);b.addEventListener('pointerdown',fn);return [b,fn]});const openButton=document.getElementById('open');openButton.addEventListener('click',start);window.addEventListener('keydown',key);document.addEventListener('visibilitychange',visibility);
 const clock=setInterval(()=>{if(phase==='choose'){const left=deadline-performance.now();q('.cham-time').value=Math.max(0,left/Math.max(650,1400-score*45)*100);if(left<=0)finish(null)}},40);controls();
 return ()=>{active=false;clear();clearInterval(clock);padListeners.forEach(([b,fn])=>b.removeEventListener('pointerdown',fn));openButton.removeEventListener('click',start);window.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',visibility)};
}
